-- Repeated seed never overwrites edited records, receipts or reference identities.
SELECT v.id::uuid,v.workspace_id::uuid,v.provider,v.legacy_key,v.company_key,v.display_name,v.synthetic,e.id FROM (VALUES
('20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','Synthetic','PPO-SIM','SYN-A','SYN Greenhouse Demonstration',true),
('20000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000001','Synthetic','PPO-SIM','SYN-B','SYN Greenhouse Demonstration',true),
('20000000-0000-4000-8000-000000000003','10000000-0000-4000-8000-000000000002','Synthetic','PPO-SIM','SYN-C','SYN isolation company',true)) v(id,workspace_id,provider,legacy_key,company_key,display_name,synthetic) JOIN ppo.erp_connections e ON e.workspace_id=v.workspace_id::uuid AND e.provider=v.provider AND e.external_connection_key=v.legacy_key ON CONFLICT DO NOTHING;
SELECT v.workspace_id::uuid,v.user_id::uuid,v.company_id::uuid,v.capability,v.company_id::uuid FROM (VALUES
('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','service.ticket.read'),
('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','service.ticket.edit'),
('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000001','service.ticket.read'),
('10000000-0000-4000-8000-000000000002','30000000-0000-4000-8000-000000000004','20000000-0000-4000-8000-000000000003','service.ticket.read')) v(workspace_id,user_id,company_id,capability) ON CONFLICT DO NOTHING;
SELECT ('40000000-0000-4000-8000-00000000000'||n)::uuid,workspace_id,id,'SYN-PPO-TKT-00000'||n,
  CASE WHEN n=1 THEN 'Prepare an irrigation controller inspection' ELSE 'Restricted synthetic request '||n END,
  'Synthetic intermittent sensor reading; cause unverified.','2026-09-05T00:00:00Z','PlannedMaintenance',
  'SYN requester; coordinator to confirm identity',true,'Normal',
  CASE WHEN n=3 THEN '30000000-0000-4000-8000-000000000004'::uuid ELSE '30000000-0000-4000-8000-000000000001'::uuid END,
  'New','2026-09-05T00:00:00Z',
  CASE WHEN n=3 THEN '30000000-0000-4000-8000-000000000004'::uuid ELSE '30000000-0000-4000-8000-000000000001'::uuid END,
  '2026-09-05T00:00:00Z',
  CASE WHEN n=3 THEN '30000000-0000-4000-8000-000000000004'::uuid ELSE '30000000-0000-4000-8000-000000000001'::uuid END
FROM (SELECT c.*,right(c.id::text,1)::integer AS n FROM ppo.companies c) s
ON CONFLICT DO NOTHING;












SELECT v.id::uuid,c.workspace_id,c.id,v.actor::uuid,v.actor::uuid,'2026-09-05T00:00:00Z','2026-09-05T00:00:00Z',v.org::uuid,c.erp_connection_id,c.erp_company_id,'Customer',v.external_key,'Proposed','2026-01-01T00:00:00Z'
FROM (VALUES
('84000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','50000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','000Ab-C.01'),
('84000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000002','50000000-0000-4000-8000-000000000003','30000000-0000-4000-8000-000000000001','000ab-C.01')) v(id,company,org,actor,external_key) JOIN ppo.companies c ON c.id=v.company::uuid ON CONFLICT DO NOTHING;


